    private String setupPage(TwoFactorService.SetupToken st, String otpAuthUri, String token) {
        return setupPageWithError(st, otpAuthUri, token, null);
    }

    private String setupPageWithError(TwoFactorService.SetupToken st, String otpAuthUri, String token, String error) {
        // QR is rendered locally (inline SVG) so the TOTP secret never leaves this server.
        String qrMarkup = qrSvg(otpAuthUri);

        String errorHtml = (error != null)
                ? "<div class=\"error-banner\"><svg style=\"flex:none;width:22px;height:22px\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M12 3 22.5 21H1.5z\" fill=\"none\" stroke=\"#e2554f\" stroke-width=\"2\" stroke-linejoin=\"round\"/><rect x=\"11\" y=\"9\" width=\"2\" height=\"6\" fill=\"#e2554f\"/><rect x=\"11\" y=\"17\" width=\"2\" height=\"2\" fill=\"#e2554f\"/></svg> " + escapeHtml(error) + "</div>"
                : "";

        return """
            <!DOCTYPE html>
            <html lang="en">
            <head>
                <meta charset="UTF-8">
                <meta name="viewport" content="width=device-width, initial-scale=1.0">
                <title>ServerAUTH — 2FA Setup</title>
                <style>%s</style>
            </head>
            <body>
                <div class="card">
                    %s
                    <h1><svg class="h1-icon" viewBox="0 0 24 24" fill="none"><path d="M12 2 4 5v6c0 5 3.4 8 8 11 4.6-3 8-6 8-11V5l-8-3z" fill="#4f9d2f" stroke="#2c6b16" stroke-width="1.6"/><path d="M8.5 12.2l2.4 2.4 4.6-4.8" stroke="#0c2107" stroke-width="2.2" stroke-linecap="square" fill="none"/></svg> Two-Factor Authentication</h1>
                    <p class="subtitle">Setting up 2FA for <strong>%s</strong></p>

                    <div class="qr-container">
                        %s
                    </div>

                    <p style="text-align:center; color:#888; font-size:0.9rem;">
                        Can't scan? Click the key below to copy it:
                    </p>
                    <div class="secret-box" onclick="navigator.clipboard.writeText('%s')" title="Click to copy">%s</div>

                    <ol class="steps">
                        <li>Open <strong>Google Authenticator</strong> (or any TOTP app)</li>
                        <li>Scan the QR code above or enter the key manually</li>
                        <li>Enter the 6-digit code below to verify and activate 2FA</li>
                    </ol>

                    <form class="verify-form" method="POST" action="/verify">
                        <input type="hidden" name="token" value="%s">
                        <input type="text" name="code" maxlength="6" pattern="[0-9]{6}"
                               placeholder="000000" autocomplete="off" autofocus required>
                        <button type="submit">Verify &amp; Enable</button>
                    </form>
                </div>
            </body>
            </html>
            """.formatted(
                CSS,
                errorHtml,
                escapeHtml(st.playerName()),
                qrMarkup,
                escapeHtml(st.secret()),
                escapeHtml(st.secret()),
                escapeHtml(token)
        );
    }

