    private String backupCodesHtml(TwoFactorService.SetupToken st) {
        StringBuilder sb = new StringBuilder();
        for (String code : st.backupCodesPlain()) {
            sb.append("<span>").append(escapeHtml(code)).append("</span>\n");
        }
        return sb.toString();
    }

